"use client";
import { useState } from "react";
export function SubmitWantOffer({ wantId, products }: { wantId: string; products: { id: string; name: string }[] }) {
  const [message, setMessage] = useState(""); const [busy, setBusy] = useState(false);
  async function submit(e: React.FormEvent<HTMLFormElement>) { e.preventDefault(); const f = new FormData(e.currentTarget); setBusy(true); try { const r = await fetch("/api/vendor/offers", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ wantId, productId: f.get("productId") || null, price: Number(f.get("price")), quantity: Number(f.get("quantity")), shipping: Number(f.get("shipping")), delivery: f.get("delivery"), condition: f.get("condition"), warranty: f.get("warranty"), message: f.get("message"), expiresAt: new Date(String(f.get("expiry"))).toISOString() }) }); const d = await r.json(); if (!r.ok) throw new Error(d.error); setMessage("Offer submitted. Manage revisions from My Offers."); } catch(e) { setMessage(e instanceof Error ? e.message : "Could not submit offer."); } finally { setBusy(false); } }
  return <form onSubmit={e => void submit(e)} className="joro-form mt-6 grid gap-4 rounded-2xl bg-white p-6 sm:grid-cols-2"><h2 className="text-xl font-bold sm:col-span-2">Submit an offer</h2><label>Matching product<select name="productId"><option value="">Link a product later</option>{products.map(p => <option value={p.id} key={p.id}>{p.name}</option>)}</select></label><label>Unit price PKR<input type="number" name="price" min={1} step="0.01" required /></label><label>Quantity<input type="number" name="quantity" min={1} defaultValue={1} required /></label><label>Delivery charge PKR<input name="shipping" type="number" min={0} step="0.01" defaultValue={0} required /></label><label>Estimated delivery<input name="delivery" maxLength={300} required /></label><label>Condition<select name="condition"><option>New</option><option>Used</option><option>Refurbished</option></select></label><label>Warranty<input name="warranty" maxLength={1000} /></label><label>Offer expiry<input name="expiry" type="datetime-local" required /></label><label>Message<textarea name="message" maxLength={5000} /></label><button disabled={busy} className="self-end rounded-xl bg-brand-primary p-3 font-bold">Submit offer</button><p role="status" className="sm:col-span-2">{message}</p></form>;
}